<dialog class="lunch-admin-dialog" id="lunch-settings-dialog"><div class="lunch-dialog-head"><h2>Configurações de pedido</h2><button type="button" data-close aria-label="Fechar"><i class="bi bi-x-lg"></i></button></div><form method="post"><input type="hidden" name="csrf" value="<?=adm_h($csrf)?>"><input type="hidden" name="action" value="settings"><label class="form-label">Preço da quentinha (R$)</label><div class="lunch-currency"><span>R$</span><input id="price-reais" name="price_reais" inputmode="decimal" value="<?=number_format((int)$s['price_cents']/100,2,',','.')?>" required></div><p class="form-text">Exemplo: 20,00</p><h3 class="h6 mt-4">Limites de escolha</h3><label class="d-block mb-2"><input type="radio" name="limit_mode" value="total" <?=$s['limit_mode']==='total'?'checked':''?>> Limite total por quentinha</label><label class="d-block mb-3"><input type="radio" name="limit_mode" value="category" <?=$s['limit_mode']==='category'?'checked':''?>> Limite por categoria</label><div id="total-limit-fields" class="mb-3"><label class="form-label">Máximo de escolhas por quentinha</label><input class="form-control" name="max_choices" type="number" min="1" max="30" value="<?=adm_h($s['max_choices'])?>" required></div><div id="category-limit-fields" class="lunch-category-fields mb-4"><p class="small text-muted">Use 0 para desabilitar escolhas nessa categoria.</p><?php $limits=json_decode((string)($s['category_limits']??'{}'),true)?:[];foreach(['Acompanhamentos','Carnes','Saladas','Tortas e assados'] as $cat):?><label><span><?=adm_h($cat)?></span><input class="form-control" name="category_limits[<?=adm_h($cat)?>]" type="number" min="0" max="30" value="<?=adm_h($limits[$cat]??0)?>" required></label><?php endforeach;?></div><label class="d-flex gap-2 mb-4"><input type="checkbox" name="orders_enabled" <?=$s['orders_enabled']?'checked':''?>> Aceitar pedidos online</label><div class="lunch-dialog-footer"><button type="button" data-close class="btn btn-outline-secondary">Cancelar</button><button class="btn btn-bia">Salvar configurações</button></div></form></dialog><script type="application/json" id="dish-existing"><?=json_encode(array_map(fn($item)=>['name'=>$item['name'],'active'=>(bool)$item['active']],$items),JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script><script src="/assets/js/admin-lunch-actions.js?v=1" defer></script>
