<section class="content-card"><div class="content-heading"><h2>Pedidos recentes</h2></div><div class="table-responsive"><table class="table"><thead><tr><th>#</th><th>Cliente / endereço</th><th>Quentinhas</th><th>Valor</th><th>Pagamento</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=adm_h($o['id'])?></td><td><?=adm_h($o['customer_name'])?><br><small><?=adm_h($o['address'])?>, <?=adm_h($o['neighborhood'])?><br>Referência: <?=adm_h($o['reference_point'])?><br><?=adm_h($o['customer_phone'])?></small></td><td><strong><?=adm_h($o['quantity'])?></strong><?php foreach(($details[(int)$o['id']]??[]) as $number=>$box):?><div class="small text-secondary mt-2"><strong>Quentinha <?=adm_h($number)?> — <?=adm_h($box['name'])?>:</strong> <?=adm_h(implode(', ',$box['items']))?></div><?php endforeach;?></td><td>R$ <?=number_format($o['total_cents']/100,2,',','.')?></td><td><?=adm_h($o['payment_method']==='pix'?'Pix':'Cartão')?> · <?=adm_h($o['payment_status']==='paid'?'Pago':'Pendente')?><?php if($o['payment_status']==='pending'&&$o['status']!=='cancelled'):?><form method="post" class="mt-2" onsubmit="return confirm('O pagamento foi realmente recebido?')"><input type="hidden" name="csrf" value="<?=adm_h($csrf)?>"><input type="hidden" name="action" value="paid"><input type="hidden" name="id" value="<?=adm_h($o['id'])?>"><button class="btn btn-outline-secondary btn-sm">Confirmar recebimento</button></form><?php endif;?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=adm_h($csrf)?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=adm_h($o['id'])?>"><select class="form-select" name="status"><?php foreach(['pending'=>'Pendente','accepted'=>'Aceito','preparing'=>'Preparando','out_for_delivery'=>'Em entrega','delivered'=>'Entregue','cancelled'=>'Cancelado'] as $key=>$value):?><option value="<?=$key?>" <?=$o['status']===$key?'selected':''?>><?=$value?></option><?php endforeach;?></select><button class="btn btn-bia btn-sm mt-2">Atualizar</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php adm_end();